'use strict';
let splitPreview=null,previewToken=0,previewTimer=null,previewWorker=null,previewJob=null;
function clearSplitPreview(){splitPreview=null;previewToken++;clearTimeout(previewTimer);$('splitResult').textContent='Настройте чувствительность для предпросмотра.'}
function drawSplitPreview(c){if(!splitPreview)return;const p=splitPreview,ratio=canvas.width/(canvas.getBoundingClientRect().width||canvas.width),colors=['#dc4f63','#378cc9','#ab6ad0','#3f9f73','#db9133','#747ee4'];c.save();c.drawImage(p.overlay,p.rect.x,p.rect.y);c.lineWidth=1.5*ratio;c.font='bold '+Math.round(12*ratio)+'px system-ui';p.groups.forEach((g,i)=>{const x=p.rect.x+g.x,y=p.rect.y+g.y,color=colors[i%colors.length];c.strokeStyle=color;c.strokeRect(x,y,g.w,g.h);const lx=Math.max(0,Math.min(canvas.width-28*ratio,x)),ly=Math.max(0,y-21*ratio);c.fillStyle=color;c.fillRect(lx,ly,28*ratio,20*ratio);c.fillStyle='white';c.fillText(String(i+1),lx+6*ratio,ly+14*ratio)});c.restore()}
function acceptPreview(message){const job=previewJob;if(!job||message.token!==previewToken)return;if(message.error){splitPreview=null;$('splitResult').textContent=message.error;render();return}const result=message.result,ids=new Map();result.groups.forEach((g,i)=>g.ids.forEach(id=>ids.set(id,i)));const colors=[[220,79,99],[55,140,201],[171,106,208],[63,159,115],[219,145,51],[116,126,228]],overlay=off(job.rect.w,job.rect.h),c=overlay.getContext('2d'),pixels=c.createImageData(job.rect.w,job.rect.h);for(let p=0;p<result.labels.length;p++){const i=ids.get(result.labels[p]);if(i===undefined)continue;const color=colors[i%colors.length];pixels.data[p*4]=color[0];pixels.data[p*4+1]=color[1];pixels.data[p*4+2]=color[2];pixels.data[p*4+3]=155}c.putImageData(pixels,0,0);splitPreview={rect:job.rect,groups:result.groups,overlay};$('splitResult').textContent='Предпросмотр: '+result.groups.length+' объектов. Нажмите кнопку, чтобы разделить.';render()}
function runPreview(job){previewJob=job;if(typeof Worker!=='undefined')try{if(!previewWorker){previewWorker=new Worker('preview-worker.js');previewWorker.onmessage=e=>acceptPreview(e.data);previewWorker.onerror=()=>{previewWorker.terminate();previewWorker=null;if(previewJob?.token===previewToken)runPreviewFallback(previewJob)}}previewWorker.postMessage(job);return}catch{previewWorker=null}runPreviewFallback(job)}
function runPreviewFallback(job){try{acceptPreview({token:job.token,result:segmentObjects(job.image,job.options)})}catch(e){acceptPreview({token:job.token,error:e.message})}}
function scheduleSplitPreview(){clearTimeout(previewTimer);const token=++previewToken;splitPreview=null;$('splitResult').textContent='Считаем объекты…';render();previewTimer=setTimeout(()=>{if(token!==previewToken)return;try{const cached=!selection?splitSession:null,shape=selection&&typeof selectionGeometry==='function'?selectionGeometry():cached?.shape,rect=shape?{...shape.bounds}:selection?{...selection}:cached?{...cached.rect}:{x:0,y:0,w:base.width,h:base.height};if(rect.w<3||rect.h<3)return;const image=bc().getImageData(rect.x,rect.y,rect.w,rect.h);if(cached)image.data.set(cached.pixels);const input=typeof maskForSegmentation==='function'?maskForSegmentation(image,rect,shape):image;runPreview({token,rect,image:input,options:{detail:+$('splitTolerance').value,tolerance:+$('backgroundTolerance').value,groupWords:$('splitMode').value==='words'}})}catch(e){$('splitResult').textContent=e.message}},180)}
$('splitMode').onchange=scheduleSplitPreview;
